from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="Data Service")
_store: dict[str, dict] = {}

class RecordIn(BaseModel):
    key: str
    value: float

@app.post("/records", status_code=201)
def create_record(record: RecordIn) -> dict:
    if record.key in _store:
        raise HTTPException(status_code=409, detail="Clé déjà existante")
    _store[record.key] = record.model_dump()
    return _store[record.key]

@app.get("/records/{key}")
def get_record(key: str) -> dict:
    if key not in _store:
        raise HTTPException(status_code=404, detail="Introuvable")
    return _store[key]
